#!/bin/sh
# Build the busycoq halting proof of 1RB1RD_1LC0RE_1LD1LC_1RA0LB_0RD0RF_0LC--- (bbchallenge 127983).
# usage: sh build.sh /path/to/busycoq
#   (a checkout of the BB6 branch of https://github.com/ccz181078/busycoq, tested at 33209bc: the proof uses its
#   Individual62.v)
# Needs Coq 8.18 or later (tested with 8.18.0). About 1 to 4 hours, nearly all of it the final evaluation run_ok.
# H127983.v is generated by tools/coq/t4engine/proof/build.sh; this script only compiles it. The file ends with
# Print Assumptions halt.
set -e
BC=${1:?give the path of a busycoq checkout (BB6 branch)}
HERE=$(cd "$(dirname "$0")" && pwd)
V="$BC/verify"
cp "$HERE"/H127983.v "$V"/
cd "$V"
[ -f Makefile.coq ] || make Makefile.coq > /dev/null
make -f Makefile.coq Individual62.vo > /dev/null 2>&1
t0=$(date +%s)
coqc -Q . BusyCoq H127983.v
echo "compiled in $(( $(date +%s) - t0 )) s"
